// Concatenates supabase/migrations/*.sql (in order) + supabase/seed.sql into
// supabase/setup.sql — a single file to paste into the Supabase SQL Editor
// for a brand-new project. Run: npm run db:setup-sql
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = "supabase/migrations";
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const parts = [
  `-- HIGHLUX MNL — complete database setup for a NEW Supabase project.
-- Paste this whole file into Supabase → SQL Editor → New query → Run (once).
-- Generated by scripts/build-setup-sql.mjs from ${files.length} migrations + seed. Do not edit by hand.
-- For later schema changes, run only the new migration files.
`,
  ...files.map((f) => `\n-- ═══ ${f} ═══\n${readFileSync(join(dir, f), "utf8")}`),
  `\n-- ═══ seed.sql (12 sample products, reviews, homepage) ═══\n${readFileSync("supabase/seed.sql", "utf8")}`,
  `\n-- Done. Next: sign up on the website, then make yourself admin:\n-- update public.profiles set role = 'admin' where id = (select id from auth.users where email = 'YOUR-EMAIL');\n`,
];
writeFileSync("supabase/setup.sql", parts.join(""));
console.log(`Wrote supabase/setup.sql (${files.length} migrations + seed)`);
